            'password' =&gt; 'newpassword123',
            'password_confirmation' =&gt; 'architecto',
            'token' =&gt; 'architecto',
        ],
    ]
);
$body = $response-&gt;getBody();
print_r(json_decode((string) $body));</code></pre></div>

